Baik, saya buat game **Binary Grid Neon** sekarang dalam satu berkas HTML5 Canvas 2D.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Binary Grid Neon — AISYS</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
  html,body { width:100%; height:100%; overflow:hidden; background:#05060f; font-family:'Segoe UI',system-ui,sans-serif; }
  #wrap { position:fixed; inset:0; display:flex; align-items:center; justify-content:center; }
  canvas { display:block; background:#05060f; touch-action:none; }
  #muteBtn {
    position:fixed; top:12px; right:12px; z-index:20;
    width:44px; height:44px; border-radius:12px; border:1px solid rgba(0,240,255,.5);
    background:rgba(10,20,40,.7); color:#7df9ff; font-size:20px; cursor:pointer;
    box-shadow:0 0 12px rgba(0,240,255,.4); backdrop-filter:blur(4px);
  }
  #muteBtn:active { transform:scale(.94); }
</style>
</head>
<body>
<div id="wrap"><canvas id="cv"></canvas></div>
<button id="muteBtn" aria-label="Mute">🔊</button>
<script>
"use strict";
// ===== AISYS HTML5 Engine — Binary Grid Neon =====
const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');
const W = 1280, H = 720;
let scale = 1, offX = 0, offY = 0;

function resize(){
  const ww = window.innerWidth, wh = window.innerHeight;
  const s = Math.min(ww / W, wh / H);
  scale = s;
  cv.width = W; cv.height = H;
  cv.style.width = (W * s) + 'px';
  cv.style.height = (H * s) + 'px';
  offX = (ww - W * s) / 2; offY = (wh - H * s) / 2;
}
window.addEventListener('resize', resize);
resize();

// ===== AUDIO =====
let audioCtx = null, muted = false;
function unlockAudio(){
  if (!audioCtx) { try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){} }
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}
function beep(freq, dur, type, vol){
  if (muted || !audioCtx) return;
  const o = audioCtx.createOscillator(), g = audioCtx.createGain();
  o.type = type || 'sine'; o.frequency.value = freq;
  g.gain.setValueAtTime(0.0001, audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(vol || 0.15, audioCtx.currentTime + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
  o.connect(g); g.connect(audioCtx.destination);
  o.start(); o.stop(audioCtx.currentTime + dur + 0.02);
}
const sfx = {
  click: () => beep(660, 0.08, 'square', 0.08),
  deselect: () => beep(330, 0.08, 'square', 0.06),
  correct: () => { beep(880,0.1,'sine',0.15); setTimeout(()=>beep(1320,0.15,'sine',0.14),90); },
  wrong: () => { beep(180,0.25,'sawtooth',0.14); setTimeout(()=>beep(120,0.3,'sawtooth',0.12),120); },
  combo: () => { beep(1046,0.08,'triangle',0.12); setTimeout(()=>beep(1568,0.12,'triangle',0.12),70); },
  over: () => { beep(400,0.2,'sawtooth',0.15); setTimeout(()=>beep(300,0.25,'sawtooth',0.14),180); setTimeout(()=>beep(200,0.4,'sawtooth',0.13),380); }
};
document.getElementById('muteBtn').addEventListener('click', (e)=>{
  e.stopPropagation(); unlockAudio(); muted = !muted;
  document.getElementById('muteBtn').textContent = muted ? '🔇' : '🔊';
});

// ===== GAME STATE =====
const STATE = { MENU:0, PLAY:1, OVER:2 };
let state = STATE.MENU;
let score = 0, lives = 3, combo = 0, bestCombo = 0;
let target = 0, selected = new Set();
let grid = []; // 16 tiles {val, x, y, w, h, pulse}
let particles = [];
let toast = null; // {text, t, color}
let shakeT = 0, shakeMag = 0;
let time = 0;
let roundStart = 0;

const BITS = [1,2,4,8,16,32,64,128];
const GRID_COLS = 4, GRID_ROWS = 4;
const TILE_W = 150, TILE_H = 110, GAP = 18;
const GRID_X = (W - (GRID_COLS * TILE_W + (GRID_COLS-1)*GAP)) / 2;
const GRID_Y = 240;

function randInt(a,b){ return Math.floor(Math.random()*(b-a+1))+a; }

function buildGrid(){
  // 16 tiles: 8 bit values, each appearing twice, shuffled
  let pool = [];
  for (const b of BITS) { pool.push(b); pool.push(b); }
  for (let i = pool.length - 1; i > 0; i--){
    const j = Math.floor(Math.random()*(i+1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  grid = [];
  for (let r = 0; r < GRID_ROWS; r++){
    for (let c = 0; c < GRID_COLS; c++){
      const idx = r*GRID_COLS + c;
      grid.push({
        val: pool[idx],
        x: GRID_X + c*(TILE_W+GAP),
        y: GRID_Y + r*(TILE_H+GAP),
        w: TILE_W, h: TILE_H,
        pulse: 0
      });
    }
  }
}

function newTarget(){
  // target = sum of 2-4 distinct bit values (so solvable with distinct tiles)
  const distinct = BITS.slice();
  for (let i = distinct.length-1; i>0; i--){ const j=Math.floor(Math.random()*(i+1)); [distinct[i],distinct[j]]=[distinct[j],distinct[i]]; }
  const count = randInt(2,4);
  let sum = 0;
  for (let i = 0; i < count; i++) sum += distinct[i];
  target = sum;
  selected.clear();
  roundStart = time;
}

function startGame(){
  score = 0; lives = 3; combo = 0; bestCombo = 0;
  buildGrid(); newTarget();
  particles = []; toast = null; shakeT = 0;
  state = STATE.PLAY;
  unlockAudio();
}

function addParticles(x, y, color, n){
  for (let i = 0; i < n; i++){
    const a = Math.random()*Math.PI*2, sp = 60 + Math.random()*220;
    particles.push({ x, y, vx: Math.cos(a)*sp, vy: Math.sin(a)*sp, life: 0.6+Math.random()*0.5, max: 1.1, color, size: 2+Math.random()*3 });
  }
}

function showToast(text, color){ toast = { text, t: 1.6, color: color || '#7df9ff' }; }

function selectedSum(){
  let s = 0;
  for (const i of selected) s += grid[i].val;
  return s;
}

// ===== INPUT =====
function pointerToCanvas(e){
  const rect = cv.getBoundingClientRect();
  const cx = (e.clientX - rect.left) / scale;
  const cy = (e.clientY - rect.top) / scale;
  return { x: cx, y: cy };
}

function handleTap(x, y){
  unlockAudio();
  if (state === STATE.MENU){
    startGame(); return;
  }
  if (state === STATE.OVER){
    // restart button area
    if (x > W/2-140 && x < W/2+140 && y > 500 && y < 570){ startGame(); }
    return;
  }
  // PLAY
  // confirm button
  if (x > W/2-160 && x < W/2+160 && y > 640 && y < 700){
    confirmSelection(); return;
  }
  // reset button
  if (x > W/2+180 && x < W/2+300 && y > 640 && y < 700){
    selected.clear(); sfx.deselect(); return;
  }
  // tiles
  for (let i = 0; i < grid.length; i++){
    const t = grid[i];
    if (x >= t.x && x <= t.x+t.w && y >= t.y && y <= t.y+t.h){
      if (selected.has(i)){ selected.delete(i); sfx.deselect(); }
      else { selected.add(i); sfx.click(); t.pulse = 1; addParticles(t.x+t.w/2, t.y+t.h/2, '#00f0ff', 6); }
      return;
    }
  }
}

function confirmSelection(){
  if (selected.size === 0){ showToast('Pilih dulu ubin bit-nya!', '#ff5fa2'); return; }
  const sum = selectedSum();
  if (sum === target){
    combo++;
    if (combo > bestCombo) bestCombo = combo;
    const gain = 100 + combo * 25;
    score += gain;
    sfx.correct();
    if (combo >= 2) sfx.combo();
    showToast('Benar! +' + gain + (combo >= 2 ? '  (Kombo x'+combo+')' : ''), '#39ff9e');
    // particles on all selected tiles
    for (const i of selected){ const t = grid[i]; addParticles(t.x+t.w/2, t.y+t.h/2, '#39ff9e', 12); }
    selected.clear();
    newTarget();
  } else {
    combo = 0;
    lives--;
    sfx.wrong();
    shakeT = 0.35; shakeMag = 10;
    showToast('Salah! ' + sum + ' ≠ ' + target, '#ff5fa2');
    selected.clear();
    if (lives <= 0){
      state = STATE.OVER;
      sfx.over();
    }
  }
}

cv.addEventListener('pointerdown', (e)=>{ e.preventDefault(); const p = pointerToCanvas(e); handleTap(p.x, p.y); });
window.addEventListener('keydown', (e)=>{
  if (e.key === 'Enter' || e.key === ' '){
    e.preventDefault(); unlockAudio();
    if (state === STATE.MENU) startGame();
    else if (state === STATE.OVER) startGame();
    else if (state === STATE.PLAY) confirmSelection();
  }
  if (e.key === 'r' || e.key === 'R'){ if (state === STATE.PLAY){ selected.clear(); sfx.deselect(); } }
});

// ===== UPDATE =====
function update(dt){
  time += dt;
  if (toast){ toast.t -= dt; if (toast.t <= 0) toast = null; }
  if (shakeT > 0) shakeT -= dt;
  for (const t of grid){ if (t.pulse > 0) t.pulse = Math.max(0, t.pulse - dt*3); }
  for (let i = particles.length-1; i >= 0; i--){
    const p = particles[i];
    p.x += p.vx*dt; p.y += p.vy*dt; p.vy += 200*dt; p.life -= dt;
    if (p.life <= 0) particles.splice(i,1);
  }
}

// ===== DRAW HELPERS =====
function roundRect(x,y,w,h,r){
  ctx.beginPath();
  ctx.moveTo(x+r,y);
  ctx.arcTo(x+w,y,x+w,y+h,r);
  ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r);
  ctx.arcTo(x,y,x+w,y,r);
  ctx.closePath();
}

function drawBackground(){
  const g = ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,'#0a0e2a'); g.addColorStop(0.5,'#0d0620'); g.addColorStop(1,'#05060f');
  ctx.fillStyle = g; ctx.fillRect(0,0,W,H);
  // grid lines glow
  ctx.save();
  ctx.strokeStyle = 'rgba(0,240,255,0.06)'; ctx.lineWidth = 1;
  for (let x = 0; x < W; x += 60){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
  for (let y = 0; y < H; y += 60){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
  ctx.restore();
  // vignette glow blobs
  const b1 = ctx.createRadialGradient(200,150,0,200,150,400);
  b1.addColorStop(0,'rgba(0,240,255,0.12)'); b1.addColorStop(1,'rgba(0,240,255,0)');
  ctx.fillStyle = b1; ctx.fillRect(0,0,W,H);
  const b2 = ctx.createRadialGradient(1080,600,0,1080,600,420);
  b2.addColorStop(0,'rgba(255,0,200,0.12)'); b2.addColorStop(1,'rgba(255,0,200,0)');
  ctx.fillStyle = b2; ctx.fillRect(0,0,W,H);
}

function drawWatermark(){
  ctx.save();
  ctx.globalAlpha = 0.35; ctx.fillStyle = '#ffffff';
  ctx.font = '14px "Segoe UI",sans-serif'; ctx.textAlign = 'right';
  ctx.fillText('AISYS HTML5 Engine', W-20, H-14);
  ctx.restore();
}

function drawTile(t, i){
  const sel = selected.has(i);
  const pulse = t.pulse;
  ctx.save();
  const cx = t.x + t.w/2, cy = t.y + t.h/2;
  const grow = pulse * 6;
  const x = t.x - grow/2, y = t.y - grow/2, w = t.w + grow, h = t.h + grow;

  // shadow / glow
  ctx.shadowBlur = sel ? 28 : 12;
  ctx.shadowColor = sel ? '#00f0ff' : 'rgba(120,0,255,0.5)';

  const g = ctx.createLinearGradient(x, y, x, y+h);
  if (sel){
    g.addColorStop(0,'rgba(0,240,255,0.35)');
    g.addColorStop(1,'rgba(0,120,255,0.25)');
  } else {
    g.addColorStop(0,'rgba(30,20,60,0.95)');
    g.addColorStop(1,'rgba(15,10,35,0.95)');
  }
  ctx.fillStyle = g;
  roundRect(x, y, w, h, 16); ctx.fill();

  ctx.shadowBlur = 0;
  ctx.lineWidth = sel ? 3 : 1.5;
  ctx.strokeStyle = sel ? '#00f0ff' : 'rgba(160,80,255,0.55)';
  roundRect(x, y, w, h, 16); ctx.stroke();

  // value text
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 44px "Segoe UI",sans-serif';
  if (sel){
    ctx.shadowBlur = 18; ctx.shadowColor = '#00f0ff';
    ctx.fillStyle = '#eaffff';
  } else {
    ctx.fillStyle = '#c9b8ff';
  }
  ctx.fillText(String(t.val), cx, cy - 6);
  ctx.shadowBlur = 0;

  // bit label
  ctx.font = '13px "Segoe UI",sans-serif';
  ctx.fillStyle = sel ? 'rgba(180,255,255,0.9)' : 'rgba(160,140,220,0.7)';
  ctx.fillText('bit ' + t.val, cx, cy + 30);

  ctx.restore();
}

function drawHUD(){
  // top bar
  ctx.save();
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.font = 'bold 22px "Segoe UI",sans-serif';
  ctx.fillStyle = '#7df9ff'; ctx.shadowBlur = 12; ctx.shadowColor = '#00f0ff';
  ctx.fillText('SKOR ' + score, 30, 46);
  ctx.shadowBlur = 0;

  // lives
  ctx.textAlign = 'right';
  ctx.fillStyle = '#ff5fa2'; ctx.font = 'bold 22px "Segoe UI",sans-serif';
  ctx.shadowBlur = 10; ctx.shadowColor = '#ff00c8';
  ctx.fillText('NYAWA ' + '♥'.repeat(Math.max(0,lives)), W-30, 46);
  ctx.shadowBlur = 0;

  // combo
  if (combo >= 2){
    ctx.textAlign = 'center';
    ctx.font = 'bold 20px "Segoe UI",sans-serif';
    ctx.fillStyle = '#39ff9e'; ctx.shadowBlur = 14; ctx.shadowColor = '#39ff9e';
    ctx.fillText('KOMBO x' + combo, W/2, 46);
    ctx.shadowBlur = 0;
  }
  ctx.restore();

  // target panel
  ctx.save();
  const tw = 420, th = 120, tx = (W-tw)/2, ty = 90;
  ctx.shadowBlur = 24; ctx.shadowColor = 'rgba(255,0,200,0.6)';
  const g = ctx.createLinearGradient(tx,ty,tx,ty+th);
  g.addColorStop(0,'rgba(60,10,80,0.9)'); g.addColorStop(1,'rgba(20,5,40,0.9)');
  ctx.fillStyle = g; roundRect(tx,ty,tw,th,20); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.strokeStyle = '#ff00c8'; ctx.lineWidth = 2; roundRect(tx,ty,tw,th,20); ctx.stroke();

  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '15px "Segoe UI",sans-serif'; ctx.fillStyle = 'rgba(255,180,240,0.85)';
  ctx.fillText('TARGET DESIMAL', W/2, ty+24);
  ctx.font = 'bold 58px "Segoe UI",sans-serif';
  ctx.fillStyle = '#ffffff'; ctx.shadowBlur = 20; ctx.shadowColor = '#ff00c8';
  ctx.fillText(String(target), W/2, ty+72);
  ctx.shadowBlur = 0;
  ctx.restore();

  // prediction line
  ctx.save();
  const sum = selectedSum();
  const ok = sum === target;
  const pw = 500, ph = 54, px = (W-pw)/2, py = 570;
  ctx.shadowBlur = 16; ctx.shadowColor = ok ? '#39ff9e' : 'rgba(0,240,255,0.6)';
  const pg = ctx.createLinearGradient(px,py,px+pw,py);
  pg.addColorStop(0,'rgba(0,60,80,0.85)'); pg.addColorStop(1,'rgba(40,0,60,0.85)');
  ctx.fillStyle = pg; roundRect(px,py,pw,ph,14); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.strokeStyle = ok ? '#39ff9e' : '#00f0ff'; ctx.lineWidth = 2;
  roundRect(px,py,pw,ph,14); ctx.stroke();

  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 20px "Segoe UI",sans-serif';
  ctx.fillStyle = ok ? '#39ff9e' : '#7df9ff';
  ctx.fillText('Garis Prediksi:  ' + sum + '  /  ' + target, W/2, py+ph/2);
  ctx.restore();

  // buttons
  drawButton(W/2-160, 640, 320, 60, 'KONFIRMASI', '#39ff9e', '#0a3a2a');
  drawButton(W/2+180, 640, 120, 60, 'RESET', '#ff5fa2', '#3a0a1e');
}

function drawButton(x,y,w,h,label,color,bg){
  ctx.save();
  ctx.shadowBlur = 16; ctx.shadowColor = color;
  const g = ctx.createLinearGradient(x,y,x,y+h);
  g.addColorStop(0, bg); g.addColorStop(1, 'rgba(10,10,20,0.9)');
  ctx.fillStyle = g; roundRect(x,y,w,h,14); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.strokeStyle = color; ctx.lineWidth = 2; roundRect(x,y,w,h,14); ctx.stroke();
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 20px "Segoe UI",sans-serif'; ctx.fillStyle = color;
  ctx.fillText(label, x+w/2, y+h/2);
  ctx.restore();
}

function drawParticles(){
  for (const p of particles){
    ctx.save();
    ctx.globalAlpha = Math.max(0, p.life / p.max);
    ctx.fillStyle = p.color; ctx.shadowBlur = 12; ctx.shadowColor = p.color;
    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill();
    ctx.restore();
  }
}

function drawToast(){
  if (!toast) return;
  ctx.save();
  ctx.globalAlpha = Math.min(1, toast.t / 0.5);
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 26px "Segoe UI",sans-serif';
  ctx.fillStyle = toast.color; ctx.shadowBlur = 18; ctx.shadowColor = toast.color;
  ctx.fillText(toast.text, W/2, 200);
  ctx.restore();
}

function drawMenu(){
  drawBackground();
  ctx.save();
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 64px "Segoe UI",sans-serif';
  ctx.fillStyle = '#ffffff'; ctx.shadowBlur = 30; ctx.shadowColor = '#00f0ff';
  ctx.fillText('BINARY GRID', W/2, 220);
  ctx.font = 'bold 40px "Segoe UI",sans-serif';
  ctx.fillStyle = '#ff00c8'; ctx.shadowBlur = 24; ctx.shadowColor = '#ff00c8';
  ctx.fillText('NEON', W/2, 280);
  ctx.shadowBlur = 0;

  ctx.font = '20px "Segoe UI",sans-serif'; ctx.fillStyle = '#b8c8ff';
  ctx.fillText('Pilih ubin bit (1, 2, 4, 8, ...) yang jumlahnya', W/2, 370);
  ctx.fillText('sama dengan target desimal.', W/2, 400);

  ctx.font = '16px "Segoe UI",sans-serif'; ctx.fillStyle = 'rgba(160,180,255,0.7)';
  ctx.fillText('Contoh: target 13 → pilih 8 + 4 + 1', W/2, 450);

  drawButton(W/2-140, 520, 280, 64, 'MULAI', '#00f0ff', '#0a2a3a');

  ctx.font = '14px "Segoe UI",sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.35)';
  ctx.fillText('Built with AISYS HTML5 Engine', W/2, 660);
  ctx.fillText('STIKOM YOS SUDARSO', W/2, 682);
  ctx.restore();
}

function drawOver(){
  drawBackground();
  ctx.save();
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 56px "Segoe UI",sans-serif';
  ctx.fillStyle = '#ff5fa2'; ctx.shadowBlur = 28; ctx.shadowColor = '#ff00c8';
  ctx.fillText('GAME OVER', W/2, 220);
  ctx.shadowBlur = 0;

  ctx.font = 'bold 32px "Segoe UI",sans-serif'; ctx.fillStyle = '#7df9ff';
  ctx.fillText('Skor Akhir: ' + score, W/2, 320);
  ctx.font = '22px "Segoe UI",sans-serif'; ctx.fillStyle = '#b8c8ff';
  ctx.fillText('Kombo Terbaik: x' + bestCombo, W/2, 370);

  drawButton(W/2-140, 500, 280, 64, 'MAIN LAGI', '#39ff9e', '#0a3a2a');

  ctx.font = '14px "Segoe UI",sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.35)';
  ctx.fillText('Built with AISYS HTML5 Engine', W/2, 660);
  ctx.fillText('STIKOM YOS SUDARSO', W/2, 682);
  ctx.restore();
}

// ===== MAIN LOOP =====
let last = performance.now();
function loop(now){
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  update(dt);

  ctx.save();
  if (shakeT > 0){
    const s = shakeMag * (shakeT / 0.35);
    ctx.translate((Math.random()-0.5)*s, (Math.random()-0.5)*s);
  }

  if (state === STATE.MENU){
    drawMenu();
  } else if (state === STATE.PLAY){
    drawBackground();
    drawHUD();
    for (let i = 0; i < grid.length; i++) drawTile(grid[i], i);
    drawParticles();
    drawToast();
    drawWatermark();
  } else if (state === STATE.OVER){
    drawOver();
  }

  ctx.restore();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
</script>
</body>
</html>
<!-- END_OF_GAME -->
